WITH f AS (SELECT fight_key, max(gil) AS gil, any(gf) AS gf FROM bestiary_fights WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND claimed AND outcome = 'defeated' AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged') GROUP BY fight_key) SELECT gf, countIf(gil IS NOT NULL) AS kills, count() AS claimed, minIf(gil, gil IS NOT NULL) AS lo, maxIf(gil, gil IS NOT NULL) AS hi, quantileExactIf(0.5)(gil, gil IS NOT NULL) AS median FROM f GROUP BY gf HAVING kills > 0 ORDER BY gf IS NULL, gf
